import{_ as i,o as e,c as l,ae as t}from"./chunks/framework.FQ5RHm_v.js";const c=JSON.parse('{"title":"wvke-sdk | 완벽한 커스터마이징!","titleTemplate":false,"description":"","frontmatter":{"title":"wvke-sdk | 완벽한 커스터마이징!","titleTemplate":false},"headers":[],"relativePath":"ko/index.md","filePath":"ko/index.md"}'),s={name:"ko/index.md"};function d(r,a,n,o,h,k){return e(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="wvke-sdk" tabindex="-1">wvke-sdk <a class="header-anchor" href="#wvke-sdk" aria-label="Permalink to &quot;wvke-sdk&quot;">​</a></h1><p>wvke-sdk는 키보드와 마우스를 포함한 게이밍 주변기기와 통신하기 위한 JavaScript SDK입니다.</p><p>최신 WebHID 기술 스택을 기반으로 키보드, 마우스 및 기타 주변기기의 심층 맞춤 설정과 지능형 제어를 가능하게 합니다. 게이밍 주변기기 제품의 엔드투엔드 제공을 가속화하고 게이밍 생태계 전반에 새로운 가능성을 열어줍니다. 이 프로젝트는 GDE Game Driver Engine Team이 개발 및 유지 관리합니다.</p><h2 id="sdk-유형" tabindex="-1">SDK 유형 <a class="header-anchor" href="#sdk-유형" aria-label="Permalink to &quot;SDK 유형&quot;">​</a></h2><h3 id="⌨️-리니어-키보드" tabindex="-1">⌨️ 리니어 키보드 <a class="header-anchor" href="#⌨️-리니어-키보드" aria-label="Permalink to &quot;⌨️ 리니어 키보드&quot;">​</a></h3><p>기계식 키보드용으로 구축:</p><ul><li>키 매핑 및 레이어 전환</li><li>RGB 조명 제어</li><li>WebHID 인증, 인증 장치 목록, 장치 초기화</li><li>RT 전행정 스위치, 작동 트래블, 세이프 존 조정</li><li>매크로 기록 및 재생</li><li>폴링 레이트 조정 (1KHz-8KHz)</li><li>시스템 모드 전환 (Windows/Mac)</li></ul><h3 id="🖱️-마우스-sdk" tabindex="-1">🖱️ 마우스 SDK <a class="header-anchor" href="#🖱️-마우스-sdk" aria-label="Permalink to &quot;🖱️ 마우스 SDK&quot;">​</a></h3><p>게이밍 마우스용으로 구축:</p><ul><li>DPI 조정 (400-16000 DPI)</li><li>버튼 프로그래밍 및 매크로</li><li>RGB 조명 커스터마이징</li><li>리프트오프 거리 조정</li><li>폴링 최적화</li></ul><h2 id="특징" tabindex="-1">특징 <a class="header-anchor" href="#특징" aria-label="Permalink to &quot;특징&quot;">​</a></h2><ul><li>최신 JavaScript/TypeScript 지원</li><li>WebHID 하드웨어 통신</li><li>완전한 조명 제어 API</li><li>키 매핑 및 매크로 API</li><li>RT 트래블, 고급 키 API, 장치 초기화</li><li>마우스 DPI 및 버튼 매핑 API</li><li>범용 사용자 정의 업그레이드 서비스</li><li>상세한 API 문서</li></ul><h2 id="튜토리얼" tabindex="-1">튜토리얼 <a class="header-anchor" href="#튜토리얼" aria-label="Permalink to &quot;튜토리얼&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wvke-sdk</span></span></code></pre></div><p>자세한 사용법은 <a href="/wvke.sdkdoc/docs/ko/api/info.html">API 문서</a>를 참조하세요.</p>',15)])])}const u=i(s,[["render",d]]);export{c as __pageData,u as default};
